package sort

import (
	"context"
	"errors"
	"fmt"
	"testing"

	"github.com/steamwo/fssql/internal/core/memory"
	"github.com/steamwo/fssql/internal/core/types"
	"github.com/steamwo/fssql/internal/core/vector"
	storagetemp "github.com/steamwo/fssql/internal/storage/temp"
)

type sortHarness struct { mm *memory.Manager; scope *memory.Scope; bm *memory.BufferManager; quotas *storagetemp.TemporaryMemoryManager; temp *storagetemp.QueryScope }
func newSortHarness(t testing.TB,tempLimit int64)(*sortHarness,func()){t.Helper();mm:=memory.NewManager(128<<20);scope:=mm.NewScope();bm:=memory.NewBufferManager(nil);q:=storagetemp.NewTemporaryMemoryManager(storagetemp.Limits{Global:tempLimit,DefaultResourceGroup:tempLimit,DefaultQuery:tempLimit});sm,err:=storagetemp.NewTemporaryStorageManager(t.TempDir(),q);if err!=nil{t.Fatal(err)};ts,err:=sm.NewQueryScope("default");if err!=nil{t.Fatal(err)};h:=&sortHarness{mm,scope,bm,q,ts};return h,func(){if err:=ts.Close();err!=nil{t.Fatal(err)};if err:=scope.Close();err!=nil{t.Fatal(err)};if mm.Used()!=0{t.Fatalf("memory leak=%d",mm.Used())};if q.GlobalUsed()!=0{t.Fatalf("temp leak=%d",q.GlobalUsed())}}}
func makeSortChunk(t testing.TB,h *sortHarness,start,n,total,nullEvery int)*vector.DataChunk{t.Helper();k,_:=vector.NewFlat(h.scope,h.bm,types.LogicalType{ID:types.BigInt},n);p,_:=vector.NewFlat(h.scope,h.bm,types.LogicalType{ID:types.Varchar},n);for i:=0;i<n;i++{seq:=start+i;value:=total-1-seq;if nullEvery>0&&seq%nullEvery==0{k.SetNull(i)}else{k.SetInt64(i,int64(value))};_=p.SetString(i,fmt.Sprintf("row-%06d",seq))};c,_:=vector.NewDataChunk(k,p);return c}
type sortedRow struct{valid bool;key int64;payload string}
func collectSort(t testing.TB,s *ExternalSort)[]sortedRow{t.Helper();var out []sortedRow;if err:=s.Emit(context.Background(),func(c *vector.DataChunk)error{for i:=0;i<c.Cardinality;i++{x,ok:=c.Columns[0].Int64(i);p,_:=c.Columns[1].String(i);out=append(out,sortedRow{ok,x,p})};c.Release();return nil});err!=nil{t.Fatal(err)};return out}
func runSort(t testing.TB,h *sortHarness,budget int64,keys []Key,rows int)(*ExternalSort,[]sortedRow){t.Helper();s,err:=New(Config{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.Varchar}},Keys:keys,MemoryBudget:budget,SpillBlockBytes:1024,Scope:h.scope,Buffers:h.bm,Temp:h.temp,Compression:storagetemp.CompressionRLE});if err!=nil{t.Fatal(err)};for base:=0;base<rows;base+=256{n:=rows-base;if n>256{n=256};c:=makeSortChunk(t,h,base,n,rows,0);if err:=s.Consume(context.Background(),c);err!=nil{c.Release();s.Release();t.Fatal(err)};c.Release()};return s,collectSort(t,s)}
func TestExternalSortForcedSpillEqualsInMemory(t *testing.T){h,clean:=newSortHarness(t,128<<20);defer clean();in,expected:=runSort(t,h,64<<20,[]Key{{Column:0}},4096);if in.Stats().RunsCreated!=0{t.Fatalf("in-memory runs=%d",in.Stats().RunsCreated)};in.Release();ext,actual:=runSort(t,h,4<<10,[]Key{{Column:0}},4096);st:=ext.Stats();if st.RunsCreated<2||st.MergePasses==0||st.SpillPages==0{t.Fatalf("expected external multi-run merge stats %+v",st)};if len(actual)!=len(expected){t.Fatalf("len=%d want=%d",len(actual),len(expected))};for i:=range expected{if actual[i]!=expected[i]{t.Fatalf("row %d=%+v want %+v",i,actual[i],expected[i])};if i>0&&actual[i-1].key>actual[i].key{t.Fatalf("not sorted at %d",i)}};ext.Release();if h.temp.Used()!=0||h.temp.OwnedFiles()!=0{t.Fatalf("temp used=%d files=%d",h.temp.Used(),h.temp.OwnedFiles())}}
func TestSortNullOrderingAndDescending(t *testing.T){h,clean:=newSortHarness(t,32<<20);defer clean();s,err:=New(Config{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.Varchar}},Keys:[]Key{{Column:0,Desc:true,NullsFirst:true}},MemoryBudget:4<<10,SpillBlockBytes:512,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{t.Fatal(err)};for base:=0;base<512;base+=128{c:=makeSortChunk(t,h,base,128,512,31);if err:=s.Consume(context.Background(),c);err!=nil{t.Fatal(err)};c.Release()};out:=collectSort(t,s);seenValid:=false;var prev int64;for i,r:=range out{if !r.valid{if seenValid{t.Fatalf("NULL after valid at %d",i)};continue};if !seenValid{seenValid=true;prev=r.key;continue};if prev<r.key{t.Fatalf("descending order violation %d < %d",prev,r.key)};prev=r.key};s.Release()}
func TestSortCancelAfterSpillCleansTemp(t *testing.T){h,clean:=newSortHarness(t,32<<20);defer clean();s,err:=New(Config{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.Varchar}},Keys:[]Key{{Column:0}},MemoryBudget:2<<10,SpillBlockBytes:512,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{t.Fatal(err)};for base:=0;base<1024;base+=128{c:=makeSortChunk(t,h,base,128,1024,0);if err:=s.Consume(context.Background(),c);err!=nil{t.Fatal(err)};c.Release()};if s.Stats().RunsCreated==0{t.Fatal("expected spilled runs")};ctx,cancel:=context.WithCancel(context.Background());cancel();err=s.Emit(ctx,func(c *vector.DataChunk)error{c.Release();return nil});if !errors.Is(err,context.Canceled){t.Fatalf("emit err=%v",err)};s.Release();if h.temp.Used()!=0||h.temp.OwnedFiles()!=0{t.Fatalf("temp used=%d files=%d",h.temp.Used(),h.temp.OwnedFiles())}}
func TestSortTempQuotaFailure(t *testing.T){h,clean:=newSortHarness(t,128);defer clean();s,err:=New(Config{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.Varchar}},Keys:[]Key{{Column:0}},MemoryBudget:1024,SpillBlockBytes:512,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{t.Fatal(err)};failed:=false;for base:=0;base<1024&&!failed;base+=128{c:=makeSortChunk(t,h,base,128,1024,0);err=s.Consume(context.Background(),c);c.Release();if err!=nil{failed=true}};if !failed{t.Fatal("expected temp quota failure")};s.Release();if h.temp.Used()!=0||h.temp.OwnedFiles()!=0{t.Fatalf("temp used=%d files=%d",h.temp.Used(),h.temp.OwnedFiles())}}
func BenchmarkExternalSortForcedSpill(b *testing.B){for i:=0;i<b.N;i++{h,clean:=newSortHarness(b,64<<20);s,err:=New(Config{InputTypes:[]types.LogicalType{{ID:types.BigInt},{ID:types.Varchar}},Keys:[]Key{{Column:0}},MemoryBudget:8<<10,SpillBlockBytes:2048,Scope:h.scope,Buffers:h.bm,Temp:h.temp});if err!=nil{b.Fatal(err)};for base:=0;base<2048;base+=256{c:=makeSortChunk(b,h,base,256,2048,0);if err:=s.Consume(context.Background(),c);err!=nil{b.Fatal(err)};c.Release()};if err:=s.Emit(context.Background(),func(c *vector.DataChunk)error{c.Release();return nil});err!=nil{b.Fatal(err)};s.Release();clean()}}
